import * as React from "react";

import { cn } from "../lib/cn.js";

/**
 * Card family -- ported verbatim from the same reference kit as Button (see button.tsx's header
 * comment for the porting rationale). Anatomy and slot names are unchanged: `Card` (the surface) >
 * `CardHeader` (title + description + optional action, laid out with a container-query grid so the
 * action column only appears when a `CardAction` child is present) > `CardTitle` / `CardDescription`
 * / `CardAction` > `CardContent` (body) > `CardFooter` (actions). See docs/interface-norms.md,
 * "Card composition" for when to use each slot.
 *
 * Every slot carries a `data-slot` attribute (unchanged from the reference) so a consumer can
 * target a specific slot (e.g. `[data-slot=card-header]`) without relying on class names, and so
 * `CardHeader`'s own grid can react to whether a `CardAction` is present via
 * `has-data-[slot=card-action]`.
 */

function Card({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card"
      className={cn(
        "flex flex-col gap-6 rounded-xl border bg-card py-6 text-card-foreground shadow-sm",
        className,
      )}
      {...props}
    />
  );
}

function CardHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-header"
      className={cn(
        "@container/card-header grid auto-rows-min grid-rows-[auto_auto] items-start gap-2 px-6 has-data-[slot=card-action]:grid-cols-[1fr_auto] [.border-b]:pb-6",
        className,
      )}
      {...props}
    />
  );
}

function CardTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-title"
      className={cn("leading-none font-semibold", className)}
      {...props}
    />
  );
}

function CardDescription({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-description"
      className={cn("text-sm text-muted-foreground", className)}
      {...props}
    />
  );
}

function CardAction({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-action"
      className={cn("col-start-2 row-span-2 row-start-1 self-start justify-self-end", className)}
      {...props}
    />
  );
}

function CardContent({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="card-content" className={cn("px-6", className)} {...props} />;
}

function CardFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-footer"
      className={cn("flex items-center px-6 [.border-t]:pt-6", className)}
      {...props}
    />
  );
}

export { Card, CardHeader, CardFooter, CardTitle, CardAction, CardDescription, CardContent };

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * `cn` -- Didact's class-composition helper (docs/design-principles.md §3), mirrored here from
 * packages/core/src/lib/cn.ts so `@didact/ui` has no dependency on `@didact/core`: `clsx` resolves
 * conditional/array/falsy class inputs, `tailwind-merge` then resolves conflicting Tailwind
 * utilities (e.g. a caller's `className="px-4"` overriding this component's own `px-2`) by keeping
 * the last one instead of leaving both in the DOM. Every Didact component that accepts `className`
 * must merge it LAST through this helper, not a manual array-join, so a single instance can be
 * restyled inline without fighting the base classes.
 */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}
